let st352=null;
function esc352(s){return String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));}
function norm352(s){return String(s||'').replace(/[。、，,\s「」『』（）()・％%]/g,'');}
function inputOK352(v,q){const n=norm352(v);return (q.keys||[q.a]).some(k=>n.includes(norm352(k)));}
function order352(q,i){const a=[q.a,...q.w].map((t,n)=>({t,ok:n===0}));const ps=[[1,0,2],[2,1,0],[0,2,1],[1,2,0],[2,0,1],[0,1,2]];return ps[i%ps.length].map(n=>a[n]);}
function voice352(ta,msg){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){msg.textContent='この端末では音声入力が使えません。文字入力で答えられます。';return}try{const r=new SR();r.lang='ja-JP';r.interimResults=false;msg.textContent='🎤 聞いています…';r.onresult=e=>{ta.value=e.results[0][0].transcript;msg.textContent='音声を文字にしました。';};r.onerror=()=>msg.textContent='うまく聞き取れませんでした。';r.start()}catch(e){msg.textContent='マイクを開始できませんでした。'}}
function makeQ352(u){if(u==='国づくりへの歩み')return KUNI_PRACTICE355.map(x=>({...x}));if(u==='大陸に学んだ国づくり')return DAIRIKU_PRACTICE357.map(x=>({...x}));const d=UNITS352[u],out=[];d.cards.forEach((c,i)=>{out.push({l:'b',cat:'基礎知識',type:'choice',q:c.q,a:c.a,w:c.w,ex:c.ex});out.push({l:'b',cat:'基礎知識',type:'choice',q:c.tq,a:c.a,w:[c.w[1],c.w[0]],ex:c.ex});});d.cards.forEach(c=>out.push({l:'s',cat:'資料・関連づけ',type:'choice',q:`【資料】${c.clue}\nこの資料に最も関係が深いものはどれですか。`,a:c.a,w:c.w,ex:c.ex}));d.apps.forEach(x=>out.push({l:'a',cat:'思考・活用',type:'choice',q:x.q,a:x.a,w:x.w,ex:x.ex}));return out;}
function makeTest352(u){if(u==='国づくりへの歩み')return KUNI_TEST355.map(x=>({...x}));if(u==='大陸に学んだ国づくり')return DAIRIKU_TEST357.map(x=>({...x}));const d=UNITS352[u],qs=makeQ352(u).slice(0,18);const w=d.write;qs.push({l:'t',cat:'記述',type:'input',q:w.q,a:w.a,keys:w.keys,ex:w.ex});d.synth.slice(0,1).forEach(x=>qs.push({l:'t',cat:'まとめ・思考',type:'choice',q:x.q,a:x.a,w:x.w,ex:x.ex}));return qs.slice(0,20);}
function parentMenu352(parent){const units=PARENTS352[parent];head(`社会｜${parent}`,()=>subjectGradeTerms('社会',6));A.append(e('div','card',`<div class="tiny">小学6年 社会｜教科書の流れに沿って学習</div><h2>${esc352(parent)}</h2><p>範囲が広いので、学校の教科書と同じように<b>小単元ごと</b>に分けました。</p><p class="tiny">小単元を選び、「学ぶ → 基礎10問 → 標準5問 → 応用3問 → 小単元テスト20問」の順で進められます。</p>`));units.forEach((u,i)=>A.append(btn(`${i+1}. ${u}`,()=>unitMenu352(u),'soft')));A.append(e('div','card soft','<h3>📝 大単元まとめテスト</h3><p>小単元を学んだあと、20問で全体を確認できます。</p>'));A.append(btn(`${parent} まとめテスト20問`,()=>startParentTest352(parent),'primary'));}
function unitMenu352(u){const d=UNITS352[u];head(`社会｜${u}`,()=>parentMenu352(d.parent));A.append(e('div','card',`<div class="tiny">${esc352(d.parent)} ＞ 小単元</div><h2>${esc352(u)}</h2><p><b>学校の単元テストに答えられる内容を、小さく分けて練習します。</b></p>`));A.append(btn('📖 学ぶ',()=>learn352(u),'primary'));A.append(btn('🌱 練習問題をやる',()=>startPractice352(u,'b'),'soft'));A.append(btn('📝 小単元テスト20問',()=>startTest352(u),'soft'));}
function learn352(u){const d=UNITS352[u];head(`📖 学ぶ｜${u}`,()=>unitMenu352(u));const box=e('div','card lesson',`<h2>${esc352(u)}</h2><p class="tiny">まずここを読めば、練習問題・テストで必要な内容を確認できます。</p>`);d.learn.forEach((x,i)=>box.innerHTML+=`<div class="soc352learn"><b>${i+1}</b><span>${esc352(x)}</span></div>`);A.append(box);if(u==='国づくりへの歩み'){A.append(e('div','card kunizukuri356',`<h2>👀 図で確認しよう</h2><p class="tiny">見た目と意味を結びつけて覚えます。</p><img src="kunizukuri_kurashi_dougu.png?v=356" alt="縄文土器・弥生土器・たて穴住居・高床倉庫の比較図"><p><b>ポイント：</b>縄文時代と弥生時代では、道具やくらし方が変わりました。</p><img src="kunizukuri_kome_mura.png?v=356" alt="米づくりとむらの発達を学ぶ図"><p><b>流れ：</b>米づくりが広がる → 人々が協力する → むらが大きくなる → 国づくりへつながる</p>`));}if(u==='大陸に学んだ国づくり'){A.append(e('div','card dairiku357',`<h2>👀 図で流れを確認しよう</h2><p class="tiny">聖徳太子から奈良時代まで、政治と文化の流れを一枚で確認できます。</p><img src="dairiku_kunizukuri.png?v=357" alt="聖徳太子・遣隋使・大化の改新・律令・平城京・東大寺を学ぶ図"><p><b>流れ：</b>大陸から学ぶ → 天皇中心の政治を整える → 律令国家 → 平城京 → 仏教と天平文化</p>`));}if(u==='武士の政治が始まる'){A.append(e('div','card bushi358',`<h2>👀 図で確認しよう</h2><p class="tiny">源平の争いから鎌倉幕府、御恩と奉公、元寇までを流れで確認します。</p><img src="bushi_seiji.png?v=358" alt="武士の政治が始まる流れを学ぶ図"><p><b>流れ：</b>武士が力をつける → 源頼朝が鎌倉幕府を開く → 御恩と奉公で御家人と結びつく → 北条氏の政治 → 元寇 → 御家人の不満が高まる</p>`));}if(u==='室町文化と力をつける人々'){A.append(e('div','card muromachi359',`<h2>👀 図で確認しよう</h2><p class="tiny">室町幕府・勘合貿易・北山文化・東山文化・応仁の乱までを流れで確認します。</p><img src="muromachi_bunka.png?v=359" alt="室町文化と力をつける人々を学ぶ図"><p><b>流れ：</b>室町幕府が始まる → 足利義満が力を強める → 明との勘合貿易 → 北山文化 → 人々の力が高まる → 東山文化 → 応仁の乱 → 戦国の世へ</p>`));}A.append(btn('🔊 説明を聞く',()=>speakJP(`${u}。${d.learn.join('。')}`),'soft'));A.append(btn('🌱 基礎10問へ',()=>startPractice352(u,'b'),'primary'));}
function level352(l){return l==='b'?'🌱 基礎':l==='s'?'📘 標準':'🌟 応用';}
function startPractice352(u,l){const qs=makeQ352(u).filter(x=>x.l===l);st352={mode:'practice',u,l,qs,i:0,first:0,miss:new Set()};practiceQ352();}
function practiceQ352(){const s=st352,q=s.qs[s.i];head(`${level352(s.l)} ${s.i+1} / ${s.qs.length}｜${s.u}`,()=>unitMenu352(s.u));A.append(e('div','card',`<h2>${esc352(q.q).replace(/\n/g,'<br>')}</h2><p class="tiny">${esc352(q.cat)}</p>`));order352(q,s.i).forEach(it=>A.append(btn(it.t,()=>practiceAns352(it.ok,q),'soft')));}
function practiceAns352(ok,q){const s=st352;if(!ok){s.miss.add(s.i);head(`🌱 ここを確認｜${s.u}`,practiceQ352);A.append(e('div','card warn',`<h2>この問題の解説</h2><p><b>答え：</b>${esc352(q.a)}</p><p>${esc352(q.ex)}</p>`));A.append(btn('同じ問題をもう一度',practiceQ352,'primary'));return}if(!s.miss.has(s.i))s.first++;if(window.ponoCorrectSound)window.ponoCorrectSound();head(`○ 確認｜${s.u}`,practiceQ352);A.append(e('div','card good',`<h2>できました</h2><p><b>答え：</b>${esc352(q.a)}</p><p>${esc352(q.ex)}</p>`));s.i++;A.append(btn(s.i<s.qs.length?'次の問題へ':'結果を見る',s.i<s.qs.length?practiceQ352:practiceDone352,'primary'));}
function practiceDone352(){const s=st352,need=s.l==='b'?8:s.l==='s'?4:0,pass=s.l==='a'||s.first>=need;head(`${level352(s.l)}結果｜${s.u}`,()=>unitMenu352(s.u));A.append(e('div',`card ${pass?'good':'warn'}`,`<h2>${pass?'✨ できました':'🌱 もう一度確認'}</h2><p>初回正解 <b>${s.first} / ${s.qs.length}</b></p>${s.l!=='a'?`<p class="tiny">クリアの目安：${need} / ${s.qs.length}</p>`:''}`));if(s.l==='b'&&pass)A.append(btn('📘 標準5問へ',()=>startPractice352(s.u,'s'),'primary'));if(s.l==='s'&&pass)A.append(btn('🌟 応用3問へ',()=>startPractice352(s.u,'a'),'primary'));if(s.l==='a')A.append(btn('📝 小単元テストへ',()=>startTest352(s.u),'primary'));A.append(btn('📖 学ぶに戻る',()=>learn352(s.u),'soft'));}
function startTest352(u){const qs=u==='武士の政治が始まる'?BUSHI_TEST358:u==='室町文化と力をつける人々'?MUROMACHI_TEST359:makeTest352(u);st352={mode:'test',u,parent:UNITS352[u].parent,qs:qs.map(x=>({...x})),i:0,answers:[]};testQ352();}
function startParentTest352(parent){const units=PARENTS352[parent],pool=[];units.forEach((u,ui)=>{makeTest352(u).forEach((q,qi)=>pool.push({...q,_u:u,_rank:(qi*7+ui*3)%31}));});pool.sort((a,b)=>a._rank-b._rank);const selected=[];let idx=0;while(selected.length<20&&idx<pool.length){const q=pool[idx++];if(!selected.some(x=>x.q===q.q))selected.push(q);}st352={mode:'parentTest',u:`${parent} まとめ`,parent,qs:selected.slice(0,20),i:0,answers:[]};testQ352();}
function testQ352(){const s=st352,q=s.qs[s.i];head(`📝 テスト ${s.i+1} / 20｜${s.u}`,()=>s.mode==='parentTest'?parentMenu352(s.parent):unitMenu352(s.u));A.append(e('div','card',`${q._u?`<div class="tiny">${esc352(q._u)}</div>`:''}<h2>${esc352(q.q).replace(/\n/g,'<br>')}</h2><p class="tiny">${esc352(q.cat)}｜5点</p>`));if(q.type==='input'){const b=e('div','card soft','<b>答えを書きましょう</b>'),ta=document.createElement('textarea');ta.rows=3;b.appendChild(ta);const m=e('div','tiny','');b.appendChild(btn('🎤 音声で答える',()=>voice352(ta,m),'soft'));b.appendChild(m);b.appendChild(btn('この答えで次へ',()=>{const v=ta.value.trim();if(!v){m.textContent='答えを入力してください。';return}record352(inputOK352(v,q),v,q)},'primary'));A.append(b)}else order352(q,s.i).forEach(it=>A.append(btn(it.t,()=>record352(it.ok,it.t,q),'soft')));A.append(e('p','tiny','※テスト中は正解・ヒント・解説を表示しません。'));}
function record352(ok,user,q){st352.answers.push({ok,user,q});st352.i++;st352.i<20?testQ352():result352();}
function result352(){const s=st352,c=s.answers.filter(x=>x.ok).length,score=c*5;head(`採点結果｜${s.u}`,()=>s.mode==='parentTest'?parentMenu352(s.parent):unitMenu352(s.u));A.append(e('div',`card ${score>=70?'good':'warn'}`,`<h2>${score}点 / 100点</h2><p>${c} / 20問 正解</p><p class="tiny">※記述はキーワードによる自動採点の目安です。</p>`));A.append(btn('📖 答えと解説を見る',review352,'primary'));if(s.mode!=='parentTest')A.append(btn('🌱 練習問題をやる',()=>startPractice352(s.u,'b'),'soft'));try{records.push({studentId:profile.id,date:new Date().toISOString(),subject:'社会',grade:6,unit:s.u,content:s.mode==='parentTest'?'大単元まとめテスト20問':'小単元テスト20問',correct:c,total:20,rate:score,score,status:`テスト ${score}点`});save()}catch(e){}}
function review352(){const s=st352;head(`答えと解説｜${s.u}`,result352);s.answers.forEach((a,i)=>A.append(e('div',`card ${a.ok?'good':'warn'}`,`<div class="tiny">問${i+1}｜${a.ok?'○':'×'}${a.q._u?`｜${esc352(a.q._u)}`:''}</div><h3>${esc352(a.q.q).replace(/\n/g,'<br>')}</h3><p><b>あなたの答え：</b>${esc352(a.user)}</p><p><b>答え：</b>${esc352(a.q.a)}</p><p>${esc352(a.q.ex)}</p>`)));}
textbookUnitHome=function(sub,g,title,term){if(sub==='社会'&&Number(g)===6&&PARENTS352[title]){parentMenu352(title);return}return oldTUH352(sub,g,title,term)};

